import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int A = sc.nextInt();
        int L = sc.nextInt();
        int N = sc.nextInt();

        int bestId = -1;
        int bestArea = Integer.MAX_VALUE;

        for (int i = 1; i <= N; i++) {
            int X = sc.nextInt();
            int Y = sc.nextInt();

            boolean fits = (A <= X && L <= Y) || (A <= Y && L <= X);

            if (fits) {
                int area = X * Y;
                if (area < bestArea || (area == bestArea && i < bestId)) {
                    bestArea = area;
                    bestId = i;
                }
            }
        }

        System.out.println(bestId);
    }
}
